script:
(function () {
  'use strict';
  // Home equity debt consolidation: unsecured debts (each paid at its own fixed monthly payment until
  // cleared) vs one home equity loan or HELOC.
  //   Current debts: interest = balance x APR / 12 each month (rounded to the cent), then the payment.
  //   Amount borrowed A = total debts + closing costs when they are financed (else costs paid in cash).
  //   Home equity loan: P = rA / (1 - (1 + r)^-n), r = rate / 12 (A / n at 0%), rounded to the cent;
  //   the last payment clears the balance.
  //   HELOC: interest-only payments (A x r, to the cent) for the draw years, then a level payment that
  //   repays A over the repayment years at the same rate.
  //   "Same payment as now": the current total monthly payment (or the scheduled payment if higher)
  //   paid into the new balance every month until it is gone.
  //   Combined loan-to-value = (mortgage + A) / home value; room = value x limit - mortgage.
  // Verified (scratchpad b4biz/hd.test.js): $100,000 at 6% over 30 years -> $599.55 a month (standard
  //   amortization table value); $22,750 at 8.5% for 15 years -> $224.03 (closed form, also re-derived
  //   by discounting the 180 payments back to the balance, within rounding); HELOC $22,750 at 8.5% -> $161.15 interest-only,
  //   then $197.43 over 20 years; default example: debts $22,000 at $690 a month, paid off in 58 months with
  //   $11,481.30 interest; 15-year loan $22,750 -> $17,574.80 interest, $40,324.80 total vs $33,481.30;
  //   paying the same $690 into the loan clears it in 38 months; CLTV ($250,000 + $22,750) / $400,000 = 68.2%;
  //   0% rate, a single debt, a payment below its interest, and an over-limit loan are all handled.
  var MAX_MONTHS = 1200;
  var MAX_DEBTS = 10;
  var DEFAULTS = [
    { name: 'Credit card 1', balance: 9000, apr: 24.99, pay: 270 },
    { name: 'Credit card 2', balance: 6000, apr: 21.99, pay: 180 },
    { name: 'Personal loan', balance: 7000, apr: 14, pay: 240 }
  ];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var rowCounter = 0;

  function cents(x) { return Math.round(x * 100) / 100; }

  // Pays a fixed amount every month until the balance is gone.
  function payDown(balance, apr, payment) {
    var r = apr / 12, bal = balance, interestTotal = 0, paid = 0;
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var interest = cents(bal * r);
      bal += interest;
      var pay = Math.min(payment, bal);
      bal -= pay; interestTotal += interest; paid += pay;
      if (bal <= 0.005) return { paidOff: true, months: m, interest: interestTotal, paid: paid };
    }
    return { paidOff: false, months: MAX_MONTHS, interest: interestTotal, paid: paid };
  }

  function levelPayment(amount, apr, months) {
    var r = apr / 12;
    if (months <= 0) return amount;
    return cents(r === 0 ? amount / months : r * amount / (1 - Math.pow(1 + r, -months)));
  }

  // Scheduled repayment: `io` interest-only months, then `n` level-payment months.
  function schedule(amount, apr, io, n) {
    var r = apr / 12, bal = amount, interestTotal = 0, paid = 0;
    var ioPay = cents(amount * r), P = levelPayment(amount, apr, n), m;
    for (m = 1; m <= io; m++) {
      var i1 = cents(bal * r);
      interestTotal += i1; paid += i1;
    }
    for (m = 1; m <= n; m++) {
      var interest = cents(bal * r);
      bal += interest;
      var pay = m === n ? bal : Math.min(P, bal);
      bal -= pay; interestTotal += interest; paid += pay;
      if (bal <= 0.005) break;
    }
    return { months: io + Math.min(m, n), interest: interestTotal, paid: paid, ioPay: ioPay, payment: P };
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function pct(x) { return (x * 100).toFixed(2) + '%'; }

  function signedMoney(x) {
    if (Math.abs(x) < 0.005) return money.format(0);
    return (x > 0 ? '+' : '−') + money.format(Math.abs(x));
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) {
      var td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    });
    body.appendChild(tr);
  }

  // ---- Debt rows (DOM methods only; user text is set as values or textContent) ----
  function el(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text) e.textContent = text;
    return e;
  }

  function numberField(id, label, value, affix, affixFirst, step, max) {
    var wrap = el('div');
    var lab = el('label', 'form-label', label);
    lab.setAttribute('for', id);
    var group = el('div', 'input-group');
    var input = el('input', 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none');
    input.type = 'number'; input.id = id; input.min = '0'; input.step = step; input.inputMode = 'decimal';
    if (max) input.max = max;
    input.value = value === '' ? '' : String(value);
    var a = el('span', 'input-affix', affix);
    if (affixFirst) { group.appendChild(a); group.appendChild(input); } else { group.appendChild(input); group.appendChild(a); }
    wrap.appendChild(lab); wrap.appendChild(group);
    return wrap;
  }

  function addDebtRow(d) {
    var list = document.getElementById('hdDebts');
    rowCounter++;
    var n = rowCounter;
    var row = el('div', 'space-y-3 rounded-xl border border-line p-4');
    row.setAttribute('data-debt-row', String(n));
    var head = el('div', 'flex items-center justify-between gap-3');
    var title = el('p', 'text-sm font-semibold text-ink', 'Debt');
    title.setAttribute('data-debt-title', '');
    var remove = el('button', 'button-secondary h-9 px-3 text-sm', 'Remove');
    remove.type = 'button';
    remove.setAttribute('data-remove', '');
    remove.addEventListener('click', function () {
      if (list.querySelectorAll('[data-debt-row]').length <= 1) return;
      row.remove();
      refreshRows();
      update();
    });
    head.appendChild(title); head.appendChild(remove);
    row.appendChild(head);

    var nameWrap = el('div');
    var nameLabel = el('label', 'form-label', 'Name');
    nameLabel.setAttribute('for', 'hdName' + n);
    var name = el('input', 'form-control');
    name.type = 'text'; name.id = 'hdName' + n; name.maxLength = 40; name.autocomplete = 'off';
    name.placeholder = 'e.g. Visa card';
    name.value = d.name || '';
    nameWrap.appendChild(nameLabel); nameWrap.appendChild(name);
    row.appendChild(nameWrap);

    var pair = el('div', 'form-row form-row-2');
    pair.appendChild(numberField('hdBal' + n, 'Balance', d.balance, '$', true, '100'));
    pair.appendChild(numberField('hdApr' + n, 'APR', d.apr, '%', false, '0.1', '100'));
    row.appendChild(pair);
    row.appendChild(numberField('hdPay' + n, 'Monthly payment', d.pay, '$', true, '5'));
    list.appendChild(row);
    refreshRows();
  }

  function refreshRows() {
    var rows = document.getElementById('hdDebts').querySelectorAll('[data-debt-row]');
    rows.forEach(function (row, i) {
      row.querySelector('[data-debt-title]').textContent = 'Debt ' + (i + 1);
      var btn = row.querySelector('[data-remove]');
      btn.disabled = rows.length <= 1;
      btn.setAttribute('aria-label', 'Remove debt ' + (i + 1));
    });
    document.getElementById('hdAdd').disabled = rows.length >= MAX_DEBTS;
  }

  function readDebts() {
    var out = [], ok = true;
    var rows = document.getElementById('hdDebts').querySelectorAll('[data-debt-row]');
    rows.forEach(function (row, i) {
      var n = row.getAttribute('data-debt-row');
      var name = document.getElementById('hdName' + n).value.trim() || ('Debt ' + (i + 1));
      var balEl = document.getElementById('hdBal' + n), aprEl = document.getElementById('hdApr' + n), payEl = document.getElementById('hdPay' + n);
      var bal = parseFloat(balEl.value), apr = parseFloat(aprEl.value), pay = parseFloat(payEl.value);
      if (balEl.value.trim() === '' || bal === 0) {
        [balEl, aprEl, payEl].forEach(function (e) { e.setAttribute('aria-invalid', 'false'); });
        return;
      }
      var badBal = isNaN(bal) || bal < 0 || bal > 1e8, badApr = isNaN(apr) || apr < 0 || apr > 100, badPay = isNaN(pay) || pay <= 0;
      balEl.setAttribute('aria-invalid', String(badBal));
      aprEl.setAttribute('aria-invalid', String(badApr));
      payEl.setAttribute('aria-invalid', String(badPay));
      if (badBal || badApr || badPay) { ok = false; return; }
      out.push({ name: name, balance: bal, apr: apr / 100, pay: pay });
    });
    return { ok: ok, debts: out };
  }

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function clearResults() {
    ['hdNewPay', 'hdPayChange', 'hdSavings', 'hdCltv'].forEach(function (id) { set(id, '–'); });
    ['hdNewPayNote', 'hdPayChangeNote', 'hdSavingsNote', 'hdCltvNote'].forEach(function (id) { set(id, ''); });
    document.getElementById('hdVerdict').hidden = true;
    document.getElementById('hdLimit').hidden = true;
    clearBody('hdCompare'); clearBody('hdDebtTable');
  }

  function update() {
    var heloc = document.getElementById('hdType').value === 'heloc';
    document.getElementById('hdLoanWrap').hidden = heloc;
    document.getElementById('hdHelocWrap').hidden = !heloc;
    var error = document.getElementById('hdError');
    var rate = num('hdRate'), years = num('hdYears'), draw = num('hdDraw'), repay = num('hdRepay'),
        costs = num('hdCosts'), value = num('hdHomeValue'), mortgage = num('hdMortgage'), limit = num('hdMaxCltv');
    var financed = document.getElementById('hdFinance').checked;
    if (document.getElementById('hdCosts').value.trim() === '') costs = 0;
    if (document.getElementById('hdMortgage').value.trim() === '') mortgage = 0;
    var input = readDebts();
    var problem = '';
    if (!input.ok) problem = 'Check the highlighted debts: balances of $0 or more, APRs from 0 to 100% and monthly payments above $0.';
    else if (!input.debts.length) problem = 'Enter at least one debt with a balance above $0.';
    else if (isNaN(value) || value <= 0 || value > 1e9) problem = 'Enter a home value above $0.';
    else if (isNaN(mortgage) || mortgage < 0 || mortgage > 1e9) problem = 'Enter a mortgage balance of $0 or more.';
    else if (isNaN(limit) || limit <= 0 || limit > 100) problem = 'Enter a borrowing limit above 0% and up to 100%.';
    else if (isNaN(rate) || rate < 0 || rate > 50) problem = 'Enter a home equity rate from 0 to 50%.';
    else if (!heloc && (isNaN(years) || years < 1 || years > 30)) problem = 'Enter a loan term from 1 to 30 years.';
    else if (heloc && (isNaN(draw) || draw < 0 || draw > 20)) problem = 'Enter an interest-only period from 0 to 20 years.';
    else if (heloc && (isNaN(repay) || repay < 1 || repay > 30)) problem = 'Enter a repayment period from 1 to 30 years.';
    else if (isNaN(costs) || costs < 0 || costs > 1e7) problem = 'Enter closing costs of $0 or more.';
    var current = [];
    if (!problem) {
      input.debts.some(function (d) {
        var s = payDown(d.balance, d.apr, d.pay);
        if (!s.paidOff) { problem = 'The payment on “' + d.name + '” does not cover its monthly interest of about ' + money.format(d.balance * d.apr / 12) + ', so it never gets paid off. Raise that payment.'; return true; }
        current.push(s);
        return false;
      });
    }
    error.hidden = !problem;
    error.textContent = problem;
    if (problem) { clearResults(); return; }

    var debts = input.debts, apr = rate / 100;
    var D = debts.reduce(function (s, d) { return s + d.balance; }, 0);
    var curPay = debts.reduce(function (s, d) { return s + d.pay; }, 0);
    var curMonths = Math.max.apply(null, current.map(function (s) { return s.months; }));
    var curInterest = current.reduce(function (s, x) { return s + x.interest; }, 0);
    var curCost = D + curInterest;
    var weighted = debts.reduce(function (s, d) { return s + d.balance * d.apr; }, 0) / D;

    var A = D + (financed ? costs : 0);
    var io = heloc ? Math.round(draw * 12) : 0, n = Math.round((heloc ? repay : years) * 12);
    var plan = schedule(A, apr, io, n);
    var firstPay = io > 0 ? plan.ioPay : plan.payment;
    var upfront = financed ? 0 : costs;
    var newCost = plan.paid + upfront;
    var fast = payDown(A, apr, Math.max(curPay, firstPay, plan.payment));
    var fastCost = fast.paid + upfront;

    set('hdNewPay', money.format(firstPay));
    set('hdNewPayNote', io > 0
      ? 'Interest only for ' + duration(io) + ', then ' + money.format(plan.payment) + ' a month for ' + duration(n) + '.'
      : 'Borrowing ' + money.format(A) + ' over ' + duration(n) + '.');
    var change = firstPay - curPay;
    set('hdPayChange', signedMoney(change));
    set('hdPayChangeNote', (change < 0 ? 'Less' : 'More') + ' each month than the ' + money.format(curPay) + ' you pay now.');
    var saving = curCost - newCost;
    set('hdSavingsLabel', saving >= 0 ? 'Total saved' : 'Extra total cost');
    set('hdSavings', money.format(Math.abs(saving)));
    set('hdSavingsNote', 'Interest and closing costs, if you pay the new balance on its schedule.');
    var cltv = (mortgage + A) / value, room = value * limit / 100 - mortgage;
    set('hdCltv', (cltv * 100).toFixed(1) + '%');
    set('hdCltvNote', room > 0 ? 'You could borrow up to about ' + money0.format(room) + ' within the ' + limit + '% limit.' : 'No equity available within the ' + limit + '% limit.');
    var limitBox = document.getElementById('hdLimit');
    limitBox.hidden = A <= room + 0.005;
    if (A > room + 0.005) set('hdLimitText', 'Borrowing ' + money.format(A) + ' would put you at ' + (cltv * 100).toFixed(1) + '% of the home’s value, above the ' + limit + '% limit. ' + (room > 0 ? 'You may only be able to borrow about ' + money0.format(room) + '.' : 'There is no room to borrow at this limit.'));

    var verdict = document.getElementById('hdVerdict');
    verdict.hidden = false;
    var fastSaving = curCost - fastCost;
    if (saving >= 0) {
      verdict.className = 'callout callout-success mt-5';
      set('hdVerdictTitle', 'Consolidating costs less overall');
      set('hdVerdictText', 'You save ' + money.format(saving) + ' in total and are debt-free ' + (plan.months <= curMonths ? duration(curMonths - plan.months) + ' sooner.' : duration(plan.months - curMonths) + ' later.') + (fast.months < plan.months ? ' Keep paying ' + money.format(Math.max(curPay, firstPay)) + ' a month and you finish in ' + duration(fast.months) + ', saving ' + money.format(fastSaving) + '.' : ''));
    } else {
      verdict.className = 'callout callout-warning mt-5';
      set('hdVerdictTitle', 'The lower rate does not make it cheaper');
      set('hdVerdictText', 'Stretched over ' + duration(plan.months) + ', the home equity ' + (heloc ? 'line' : 'loan') + ' costs ' + money.format(-saving) + ' more than paying your debts as you do now.' + (fastSaving > 0 ? ' Paying ' + money.format(Math.max(curPay, firstPay)) + ' a month instead clears it in ' + duration(fast.months) + ' and saves ' + money.format(fastSaving) + '.' : ''));
    }

    var cmp = clearBody('hdCompare');
    var fastPay = Math.max(curPay, firstPay, plan.payment);
    addRow(cmp, ['Monthly payment', money.format(curPay), io > 0 ? money.format(firstPay) + ', then ' + money.format(plan.payment) : money.format(firstPay), money.format(fastPay)]);
    addRow(cmp, ['Time to debt-free', duration(curMonths), duration(plan.months), duration(fast.months)]);
    addRow(cmp, ['Total interest', money.format(curInterest), money.format(plan.interest), money.format(fast.interest)]);
    addRow(cmp, ['Closing costs', money.format(0), money.format(costs), money.format(costs)]);
    addRow(cmp, ['Total cost (debt + interest + costs)', money.format(curCost), money.format(newCost), money.format(fastCost)]);
    addRow(cmp, ['Average rate', pct(weighted) + ' (balance-weighted)', pct(apr), pct(apr)]);
    addRow(cmp, ['Secured by your home', 'No', 'Yes', 'Yes']);

    var tb = clearBody('hdDebtTable');
    debts.forEach(function (d, i) {
      addRow(tb, [d.name, money.format(d.balance), pct(d.apr), money.format(d.pay), duration(current[i].months), money.format(current[i].interest)]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    DEFAULTS.forEach(addDebtRow);
    var form = document.getElementById('hdForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    document.getElementById('hdAdd').addEventListener('click', function () {
      if (document.getElementById('hdDebts').querySelectorAll('[data-debt-row]').length >= MAX_DEBTS) return;
      addDebtRow({ name: '', balance: '', apr: '', pay: '' });
      update();
    });
    update();
  });
})();
